const menuBtn = document.getElementById('menuBtn');
const mobileNav = document.getElementById('mobileNav');
const languageMenu = document.getElementById('languageMenu');
const languageTrigger = document.getElementById('languageTrigger');
const languageCurrent = document.getElementById('languageCurrent');

function trackEvent(name, parameters) {
  if (typeof window.gtag !== 'function') return;
  window.gtag('event', name, Object.assign({transport_type: 'beacon'}, parameters || {}));
}

function decorateOutboundLinks() {
  document.querySelectorAll('a[href*="kakobuymake.com"]').forEach(link => {
    try {
      const url = new URL(link.href);
      url.searchParams.set('utm_source', 'cssbuyvip.net');
      url.searchParams.set('utm_medium', 'referral');
      url.searchParams.set('utm_campaign', link.closest('.product-card') ? 'featured_products' : link.closest('.category-card') ? 'category_browse' : 'site_cta');
      link.href = url.toString();
    } catch (error) {}
  });
}

function setupCategoryLinks() {
  document.querySelectorAll('a.category-card[href]').forEach(card => {
    card.removeAttribute('target');
    card.style.display = 'block';
    card.style.position = 'relative';
    card.style.zIndex = '20';
    card.style.cursor = 'pointer';
    card.style.pointerEvents = 'auto';
    card.querySelectorAll('*').forEach(child => { child.style.pointerEvents = 'none'; });
  });
}
setupCategoryLinks();
decorateOutboundLinks();

document.addEventListener('click', (event) => {
  if (!(event.target instanceof Element)) return;
  const card = event.target.closest('a.category-card[href]');
  if (!card) return;
  event.preventDefault();
  trackEvent('category_click', {
    category_name: (card.querySelector('h3') || {}).textContent || 'unknown',
    link_url: card.href
  });
  window.location.assign(card.href);
}, true);

document.addEventListener('click', (event) => {
  if (!(event.target instanceof Element)) return;
  const product = event.target.closest('.product-card a[href]');
  if (product) {
    trackEvent('outbound_product_click', {
      product_name: (product.querySelector('h3') || {}).textContent || 'unknown',
      link_url: product.href
    });
    return;
  }
  const guide = event.target.closest('.guide a[href], .related-guide-grid a[href]');
  if (guide) {
    trackEvent('guide_open', {
      guide_title: (guide.querySelector('h3') || guide).textContent.trim().slice(0, 120),
      link_url: guide.href
    });
  }
});

function closeMobile() {
  if (!mobileNav || !menuBtn) return;
  mobileNav.classList.remove('open');
  menuBtn.setAttribute('aria-expanded','false');
}
if (menuBtn) menuBtn.addEventListener('click', () => {
  const open = !mobileNav.classList.contains('open');
  mobileNav.classList.toggle('open', open);
  menuBtn.setAttribute('aria-expanded', String(open));
});
document.addEventListener('click', (event) => {
  if (languageMenu && !languageMenu.contains(event.target)) languageMenu.classList.remove('open');
});
if (languageTrigger) languageTrigger.addEventListener('click', (event) => {
  event.stopPropagation();
  languageMenu.classList.toggle('open');
});
document.querySelectorAll('.language-option').forEach(option => {
  option.addEventListener('click', () => {
    languageMenu.classList.remove('open');
    applyLanguage(option.dataset.lang || 'en');
  });
});
document.querySelectorAll('.mobile-nav a').forEach(a => a.addEventListener('click', closeMobile));
window.addEventListener('resize', () => { if (window.innerWidth > 1120) closeMobile(); });

let pendingLanguage = null;

function clearGoogleTranslation() {
  const expires = 'Thu, 01 Jan 1970 00:00:00 GMT';
  document.cookie = 'googtrans=; expires=' + expires + '; path=/';
  document.cookie = 'googtrans=; expires=' + expires + '; path=/; domain=.cssbuyvip.net';
}

function setGoogleTranslation(lang) {
  const targetCodes = {zh: 'zh-CN', es: 'es', fr: 'fr', de: 'de', pt: 'pt'};
  const target = targetCodes[lang];
  const combo = document.querySelector('.goog-te-combo');
  if (!combo || !target) {
    pendingLanguage = lang;
    return false;
  }
  const faqDetails = Array.from(document.querySelectorAll('.reverse-faq-card'));
  const faqStates = faqDetails.map(item => item.open);
  const faqSection = document.querySelector('.reverse-faq-section');
  if (faqSection) faqSection.style.visibility = 'hidden';
  faqDetails.forEach(item => { item.open = true; });

  combo.value = target;
  combo.dispatchEvent(new Event('change', {bubbles: true}));

  window.setTimeout(() => {
    faqDetails.forEach((item, index) => { item.open = faqStates[index]; });
    if (faqSection) faqSection.style.visibility = '';
  }, 6000);
  pendingLanguage = null;
  return true;
}

function applyLanguage(lang) {
  const selected = translations[lang] ? lang : 'en';
  const previous = document.documentElement.lang || 'en';
  try { localStorage.setItem('cssbuyvip-language', selected); } catch (e) {}
  document.documentElement.lang = selected === 'zh' ? 'zh-CN' : selected;
  document.querySelectorAll('.language-option').forEach(o => o.classList.toggle('active', o.dataset.lang === selected));
  const names = {en:'English',zh:'简体中文',es:'Español',fr:'Français',de:'Deutsch',pt:'Português'};
  if (languageCurrent) languageCurrent.textContent = names[selected] || 'English';
  if (previous !== (selected === 'zh' ? 'zh-CN' : selected)) {
    trackEvent('language_change', {language: selected});
  }

  if (selected === 'en') {
    const combo = document.querySelector('.goog-te-combo');
    if (combo && combo.value) {
      clearGoogleTranslation();
      window.location.reload();
    }
    return;
  }
  setGoogleTranslation(selected);
}

window.googleTranslateElementInit = function() {
  if (!window.google || !google.translate || !google.translate.TranslateElement) return;
  new google.translate.TranslateElement({
    pageLanguage: 'en',
    includedLanguages: 'zh-CN,es,fr,de,pt',
    autoDisplay: false
  }, 'google_translate_element');
  window.setTimeout(() => {
    if (pendingLanguage) setGoogleTranslation(pendingLanguage);
  }, 300);
};

function initializeFullPageTranslation() {
  if (languageMenu) languageMenu.classList.add('notranslate');
  let host = document.getElementById('google_translate_element');
  if (!host) {
    host = document.createElement('div');
    host.id = 'google_translate_element';
    host.hidden = true;
    document.body.appendChild(host);
  }
  const style = document.createElement('style');
  style.textContent = '.goog-te-banner-frame,.goog-te-balloon-frame,#goog-gt-tt{display:none!important}body{top:0!important}.skiptranslate iframe{visibility:hidden!important}';
  document.head.appendChild(style);
  if (!document.querySelector('script[data-cssbuy-translate]')) {
    const script = document.createElement('script');
    script.src = 'https://translate.google.com/translate_a/element.js?cb=googleTranslateElementInit';
    script.async = true;
    script.dataset.cssbuyTranslate = 'true';
    document.head.appendChild(script);
  }
}

